import java.util.ArrayList;

public class ListSwapperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        ArrayList<String> list = new ArrayList<>(java.util.List.of("a", "b", "c"));
        ArrayList<String> returned = null;
        try {
            returned = ListSwapper.swap(list, 0, 2);
        } catch (Exception e) {
            System.out.println("FAIL  swap threw " + e);
            failures++;
        }
        check("returns the same list object", true, returned == list);
        check("list after swap(0, 2)", "[c, b, a]", String.valueOf(list));

        ArrayList<String> pair = new ArrayList<>(java.util.List.of("red", "blue"));
        try { ListSwapper.swap(pair, 0, 1); } catch (Exception e) { }
        check("adjacent swap(0, 1)", "[blue, red]", String.valueOf(pair));

        ArrayList<String> same = new ArrayList<>(java.util.List.of("x", "y"));
        try { ListSwapper.swap(same, 1, 1); } catch (Exception e) { }
        check("swap(1, 1) leaves list unchanged", "[x, y]", String.valueOf(same));

        ArrayList<String> mid = new ArrayList<>(java.util.List.of("p", "q", "r", "s"));
        try { ListSwapper.swap(mid, 1, 3); } catch (Exception e) { }
        check("swap(1, 3) in a longer list", "[p, s, r, q]", String.valueOf(mid));

        check("size is unchanged by swapping", 4, mid.size());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

