import java.util.ArrayList;

public class ListSwapper {

    public static ArrayList<String> swap(ArrayList<String> list, int i, int j) {
        String temp = list.get(i);
        list.set(i, list.get(j));
        list.set(j, temp);
        return list;
    }
}
